const test = require('node:test');
const assert = require('node:assert/strict');
const { daysBetween } = require('./daysbetween');

test('counts both end days', () => {
  assert.equal(daysBetween('2024-01-01', '2024-01-10'), 10);
});

test('a single day', () => {
  assert.equal(daysBetween('2024-05-05', '2024-05-05'), 1);
});

test('leap year span crossing Feb 29', () => {
  assert.equal(daysBetween('2024-02-28', '2024-03-01'), 3);
});

test('to earlier than from throws RangeError', () => {
  assert.throws(() => {
    daysBetween('2024-01-10', '2024-01-01');
  }, RangeError);
});

test('invalid date formats throw RangeError', () => {
  const invalid = [
    '2024-1-1',
    '24-01-01',
    '2024/01/01',
    '2024-01-31T00:00:00Z',
    'abcd-ef-gh',
    '2023-02-29', // non-leap year
    '2024-04-31', // April has 30 days
    '0999-01-01', // Year out of range (< 1000)
    '10000-01-01' // Year out of range (> 9999)
  ];
  for (const dt of invalid) {
    assert.throws(() => {
      daysBetween(dt, '2024-01-01');
    }, RangeError, `Expected RangeError for ${dt}`);
  }
});

test('non-string arguments throw TypeError', () => {
  const nonStrings = [20240101, null, undefined, {}, [], true];
  for (const ns of nonStrings) {
    assert.throws(() => {
      daysBetween(ns, '2024-01-01');
    }, TypeError, `Expected TypeError for from=${ns}`);
    assert.throws(() => {
      daysBetween('2024-01-01', ns);
    }, TypeError, `Expected TypeError for to=${ns}`);
  }
});
"}
